import (
	"bufio"
	"io"
	"os"
	"slices"
	"strconv"
)

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, m := int(nextInt()), int(nextInt())
	places := make(map[int64]struct{}, n) // current occupied positions
	for i := 0; i < n; i++ {
		places[nextInt()] = struct{}{}
	}
	for i := 0; i < m; i++ {
		from, to := nextInt(), nextInt()
		delete(places, from)
		places[to] = struct{}{}
	}
	out := make([]int64, 0, len(places))
	for x := range places {
		out = append(out, x)
	}
	slices.Sort(out)
	w := bufio.NewWriterSize(os.Stdout, 1<<16)
	defer w.Flush()
	for i, x := range out {
		if i > 0 {
			w.WriteByte(' ')
		}
		w.WriteString(strconv.FormatInt(x, 10))
	}
	w.WriteByte('\n')
}

var data []byte
var pos int

func skipSpace() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func nextToken() []byte {
	skipSpace()
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int64 {
	skipSpace()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}
